import { writeFileSync } from 'node:fs';
const B = String.fromCharCode(92); // backslash
const chars = [B, '`', '*', '_', '{', '}', '[', ']', '(', ')', '#', '+', '-', '.', '!', '<', '>', '|', ':', '"', "'", '/', '=', '~', '^', '%', '$', '@', ',', ';', '?'];
const list = [];
for (const c of chars) list.push('a' + B + c + 'b');
list.push('a' + B + 'zb');
list.push('a' + B + '5b');
list.push('a' + B + '\nb');
list.push('a' + B + '中b');
list.push('a' + B + ' b');
list.push('a' + B);
list.push('a' + B + B + 'b');
list.push(B + B);
list.push(B);
list.push('a' + B + B + B + 'b');
list.push('a' + B + B + B + B + 'b');
list.push('a' + B + '\t' + 'b');
list.push('a' + B + '\n\nb');
writeFileSync(new URL('./e1.json', import.meta.url), JSON.stringify(list, null, 1));
